package com.eldenworld.core.specialization;
import com.eldenworld.core.EldenWorldCore; import com.eldenworld.core.abilities.AbilityUtil; import net.minecraft.resources.ResourceLocation; import net.minecraft.server.level.ServerPlayer; import net.minecraft.world.entity.projectile.Projectile; import net.minecraft.world.item.ItemStack; import net.minecraft.world.item.ShieldItem; import net.minecraftforge.event.entity.living.LivingHurtEvent; import net.minecraftforge.eventbus.api.SubscribeEvent; import net.minecraftforge.fml.common.Mod; import net.minecraftforge.registries.ForgeRegistries;
@Mod.EventBusSubscriber(modid=EldenWorldCore.MOD_ID) public final class WeaponMasteryEvents { private WeaponMasteryEvents(){}
 @SubscribeEvent public static void onHurt(LivingHurtEvent e){ if(e.getSource().getEntity() instanceof ServerPlayer a){ItemStack w=a.getMainHandItem();String p=path(w);float m=1; if(AbilityUtil.has(a,SpecializationIds.NIGHTBLADE)&&any(p,"dagger","knife","sai"))m*=1.15f; if(AbilityUtil.has(a,SpecializationIds.COLOSSUS)&&any(p,"greatsword","claymore","greataxe","warhammer","great_hammer"))m*=1.15f; if(AbilityUtil.has(a,SpecializationIds.DUELIST)&&a.getOffhandItem().isEmpty()&&!w.isEmpty())m*=1.10f; if(AbilityUtil.has(a,SpecializationIds.MARKSMAN)&&e.getSource().getDirectEntity() instanceof Projectile)m*=1.12f; e.setAmount(e.getAmount()*m);} if(e.getEntity() instanceof ServerPlayer d&&AbilityUtil.has(d,SpecializationIds.BULWARK)&&(d.getMainHandItem().getItem() instanceof ShieldItem||d.getOffhandItem().getItem() instanceof ShieldItem))e.setAmount(e.getAmount()*.90f);}
 private static String path(ItemStack s){ResourceLocation id=ForgeRegistries.ITEMS.getKey(s.getItem());return id==null?"":id.getPath();} private static boolean any(String p,String...n){for(String x:n)if(p.contains(x))return true;return false;}}
